using Microsoft.VisualStudio.TestTools.UnitTesting;
using Commerce;

namespace Commerce.Tests;

[TestClass]
public class ShoppingCartTests
{
    private ShoppingCart _cart = null!;

    [TestInitialize]
    public void Setup() => _cart = new ShoppingCart();

    // --- AddItem tests ---

    [TestMethod]
    public void AddItem_SingleItem_IncludedInTotal()
    {
        _cart.AddItem("SKU-1", 10.00m, 2);

        Assert.AreEqual(20.00m, _cart.GetTotal());
    }

    [TestMethod]
    public void AddItem_MultipleItems_TotalSumsAll()
    {
        _cart.AddItem("SKU-1", 5.00m, 3);
        _cart.AddItem("SKU-2", 12.50m, 1);

        Assert.AreEqual(27.50m, _cart.GetTotal());
    }

    [TestMethod]
    public void AddItem_DuplicateSku_BothEntriesCounted()
    {
        _cart.AddItem("SKU-1", 10.00m, 1);
        _cart.AddItem("SKU-1", 10.00m, 1);

        Assert.AreEqual(20.00m, _cart.GetTotal());
    }

    // --- RemoveItem tests ---

    [TestMethod]
    public void RemoveItem_ExistingSku_ReturnsTrue()
    {
        _cart.AddItem("SKU-1", 10.00m, 1);

        Assert.IsTrue(_cart.RemoveItem("SKU-1"));
    }

    [TestMethod]
    public void RemoveItem_ExistingSku_ExcludedFromTotal()
    {
        _cart.AddItem("SKU-1", 10.00m, 1);
        _cart.AddItem("SKU-2", 5.00m, 2);

        _cart.RemoveItem("SKU-1");

        Assert.AreEqual(10.00m, _cart.GetTotal());
    }

    [TestMethod]
    public void RemoveItem_NonExistentSku_ReturnsFalse()
    {
        Assert.IsFalse(_cart.RemoveItem("NO-SUCH"));
    }

    [TestMethod]
    public void RemoveItem_DuplicateSku_RemovesAllMatches()
    {
        _cart.AddItem("SKU-1", 10.00m, 1);
        _cart.AddItem("SKU-1", 10.00m, 2);

        _cart.RemoveItem("SKU-1");

        Assert.AreEqual(0.00m, _cart.GetTotal());
    }

    // --- GetTotal tests ---

    [TestMethod]
    public void GetTotal_EmptyCart_ReturnsZero()
    {
        Assert.AreEqual(0.00m, _cart.GetTotal());
    }

    [TestMethod]
    public void GetTotal_AfterAllItemsRemoved_ReturnsZero()
    {
        _cart.AddItem("SKU-1", 25.00m, 4);
        _cart.RemoveItem("SKU-1");

        Assert.AreEqual(0.00m, _cart.GetTotal());
    }
}

